create table if not exists public.credit_transactions(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,amount integer not null,reason text not null check(reason in('referral_bonus','referred_bonus','monthly_leaderboard','admin_grant')),created_at timestamptz not null default now());create index if not exists idx_ctx_u on public.credit_transactions(user_id);create index if not exists idx_ctx_c on public.credit_transactions(created_at);create or replace function public.fn_update_credit_balance() returns trigger language plpgsql security definer as $$ begin insert into public.credits(user_id,balance) values(new.user_id,0) on conflict(user_id) do nothing;update public.credits set balance=balance+new.amount,updated_at=now() where user_id=new.user_id;if(select balance from public.credits where user_id=new.user_id)<0 then raise exception 'Insufficient credits';end if;return new;end;$$;drop trigger if exists trg_cb on public.credit_transactions;create trigger trg_cb after insert on public.credit_transactions for each row execute function public.fn_update_credit_balance();
